diagrams.business_process_flow:
@startuml
start
:Customer membuka halaman menu dan menambahkan pilihan ke keranjang;
:Customer mengisi data pemesanan pada halaman preorder;
if (Data pemesanan lengkap dan keranjang tidak kosong?) then (Ya)
  :Sistem membuat kode pesanan unik;
  :Sistem mengosongkan keranjang Customer;
else (Tidak)
  :Sistem menampilkan pesan kesalahan;
  stop
endif
:Customer diarahkan ke halaman pembayaran via WhatsApp admin;
:Admin memproses pesanan melalui dashboard admin;
switch (Aksi admin terhadap pesanan?)
case (Proses)
  :Sistem mengubah status pesanan menjadi diproses;
case (Siap)
  :Sistem mengubah status pesanan menjadi siap;
case (Batal)
  :Sistem mengubah status pesanan menjadi dibatalkan;
  stop
endswitch
:Admin menyelesaikan pesanan;
:Sistem mengubah status pesanan menjadi selesai;
:Customer melacak status pesanan menggunakan kode pesanan;
if (Pesanan sudah selesai?) then (Ya)
  :Customer memberikan rating pesanan;
else (Tidak)
  :Sistem menampilkan status pesanan berjalan;
endif
stop
@enduml

activity_diagrams.diagram_script:
@startuml
|Admin|
start
:Admin membuka halaman login;
:Admin memasukkan username dan password;
|Sistem|
:Sistem memverifikasi kredensial melalui AuthService;
if (Kredensial valid?) then (Ya)
  :Sistem membuat sesi login menggunakan Flask-Login;
  :Sistem mengarahkan Admin ke halaman dashboard;
else (Tidak)
  :Sistem menampilkan pesan kesalahan login;
  |Admin|
  :Admin memasukkan ulang username dan password;
endif
stop
@enduml

@startuml
|Admin|
start
:Admin membuka halaman manajemen menu;
:Sistem menampilkan daftar menu;
switch (Aksi yang dipilih Admin?)
case (Tambah Menu)
  :Admin mengisi formulir menu baru beserta gambar;
case (Edit Menu)
  :Admin mengubah data menu yang dipilih;
case (Aktifkan atau Nonaktifkan)
  :Admin menekan tombol toggle status menu;
endswitch
|Sistem|
if (Aksi memerlukan validasi data?) then (Ya)
  :Sistem memvalidasi data menu;
  if (Data valid?) then (Ya)
    :Sistem mengunggah gambar ke Cloudinary jika ada;
    :Sistem menyimpan perubahan menu ke database;
  else (Tidak)
    :Sistem menampilkan pesan kesalahan validasi;
  endif
else (Tidak)
  :Sistem mengubah status aktif menu secara langsung;
endif
|Admin|
:Admin melihat daftar menu terbaru;
stop
@enduml

@startuml
|Admin|
start
:Admin membuka halaman daftar pesanan;
|Sistem|
:Sistem menampilkan daftar pesanan aktif;
|Admin|
switch (Aksi yang dipilih Admin?)
case (Proses)
  :Admin menekan tombol proses pesanan;
case (Siap)
  :Admin menekan tombol tandai siap;
case (Selesai)
  :Admin menekan tombol selesaikan pesanan;
case (Batal)
  :Admin menekan tombol batalkan pesanan;
case (Hapus)
  :Admin menekan tombol hapus pesanan;
case (Walk-in)
  :Admin mengisi data pesanan walk-in;
endswitch
|Sistem|
:Sistem memperbarui status atau data pesanan sesuai aksi Admin;
:Sistem menampilkan daftar pesanan terbaru;
stop
@enduml

@startuml
|Admin|
start
:Admin membuka halaman dashboard;
|Sistem|
:Sistem menghitung ringkasan pesanan aktif dan selesai hari ini;
:Sistem menampilkan menu terlaris dan revenue mingguan;
:Sistem menampilkan distribusi sumber order dan jam ramai;
|Admin|
if (Admin ingin mengunduh laporan?) then (Ya)
  :Admin menekan tombol unduh laporan;
  |Sistem|
  :Sistem menghasilkan file laporan dan mengirimkannya ke Admin;
else (Tidak)
  :Admin tetap memantau dashboard;
endif
stop
@enduml

@startuml
|Customer|
start
:Customer membuka halaman menu;
:Customer mencari atau memilih menu yang diinginkan;
:Customer menambahkan menu ke keranjang;
:Customer membuka halaman keranjang;
switch (Aksi Customer di keranjang?)
case (Ubah Kuantitas)
  :Customer mengubah jumlah item di keranjang;
case (Hapus Item)
  :Customer menghapus item dari keranjang;
case (Lanjut Checkout)
  :Customer membuka halaman preorder dan mengisi data pemesanan;
endswitch
|Sistem|
:Sistem memvalidasi keranjang dan data pemesanan;
if (Data valid dan keranjang tidak kosong?) then (Ya)
  :Sistem membuat kode pesanan unik;
  :Sistem mengosongkan keranjang Customer;
else (Tidak)
  :Sistem menampilkan pesan kesalahan;
endif
stop
@enduml

@startuml
|Customer|
start
:Customer membuka halaman lacak pesanan;
:Customer memasukkan kode pesanan;
|Sistem|
:Sistem mencari pesanan berdasarkan kode pesanan;
if (Pesanan ditemukan?) then (Ya)
  :Sistem menampilkan status pesanan;
  if (Status pesanan selesai?) then (Ya)
    |Customer|
    :Customer memberikan rating pesanan;
    |Sistem|
    :Sistem menyimpan rating dan memperbarui rata-rata rating menu;
  else (Tidak)
    |Customer|
    :Customer membuka halaman pembayaran via WhatsApp admin;
  endif
else (Tidak)
  :Sistem menampilkan pesan pesanan tidak ditemukan;
endif
stop
@enduml

@startuml
|Customer|
start
:Customer membuka widget chatbot;
:Customer mengirim pesan ke chatbot;
|Sistem|
:Sistem mengirim pesan ke Groq API;
:Sistem menerima balasan dari model;
if (Balasan mengandung tool call?) then (Ya)
  :Sistem mengeksekusi tool terkait, seperti pencarian menu atau rekomendasi;
else (Tidak)
  :Sistem melanjutkan tanpa eksekusi tool;
endif
if (Keranjang tidak kosong dan balasan mengindikasikan checkout?) then (Ya)
  :Sistem menampilkan panel checkout kepada Customer;
else (Tidak)
  :Sistem tidak menampilkan panel checkout;
endif
|Customer|
:Customer membaca balasan chatbot;
stop
@enduml
